INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('refly-ai/refly-skills/exa', 'community', 'refly-ai', 'refly-skills', 'refly-ai/refly-skills', 'exa', 0, 0, 60, '2026-03-02T01:56:10.876Z', '2026-03-02T02:07:14.163Z', 'dcf47b7cd8f817a99470bc08f29bbe2c12097431f9ef50783aaebccb02276b1a', '{"id":"refly-ai/refly-skills/exa","name":"exa","description":{"zh":"Exa AI 技术提供基于语义搜索的开发解决方案，帮助开发者快速找到相关内容和文档","ja":"Exa AI 技術は意味検索による開発ソリューションを提供し、開発者が関連コンテンツや文書を素早く見つけることができるようにします","ko":"Exa AI 기술은 의미 검색 기반의 개발 솔루션을 제공하여 개발자가 관련 콘텐츠 및 문서를 신속하게 찾을 수 있도록 도와줍니다","es":"Exa es una habilidad de búsqueda semántica que permite encontrar contenido por significado, no por palabras clave, y descubrir documentos similares.","fr":"Exa est une compétence de recherche sémantique qui permet de trouver du contenu par signification, pas par mots-clés, et de découvrir des documents similaires.","de":"Exa ist eine Fähigkeit zur semantischen Suche, die es ermöglicht, Inhalte nach Bedeutung zu finden, nicht nach Schlüsselwörtern, und ähnliche Dokumente zu entdecken.","pt":"Exa é uma habilidade de busca semântica que permite encontrar conteúdo por significado, não por palavras-chave.","ru":"Exa - это навык семантического поиска, который позволяет найти контент по смыслу, а не по ключевым словам.","ar":"إكسا هو مهارة بحث دلالي يسمح بالبحث عن المحتوى بالمعني لا بالكلمات الرئيسية.","en":"Refly skills repository"},"seo":{"title":{"zh":"Exa AI 技术：基于语义搜索的开发解决方案","ja":"Exa AI 技術：意味検索による開発ソリューション","ko":"Exa AI 기술: 의미 검색 기반 개발 솔루션","es":"Exa: Búsqueda Semántica Avanzada","fr":"Exa: Recherche Sémantique de Pointe","de":"Exa: Erweiterte Semantische Suche","pt":"Exa: Busca Semântica Avançada","ru":"Exa: Продвинутый Семантический Поиск","ar":"إكسا: بحث семانتيكي متقدم","en":"exa"},"description":{"zh":"Exa AI 技术提供基于语义搜索的开发解决方案，帮助开发者快速找到相关内容和文档","ja":"Exa AI 技術は意味検索による開発ソリューションを提供し、開発者が関連コンテンツや文書を素早く見つけることができ