INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('rohunj/claude-build-workflow/ralph', 'community', 'rohunj', 'claude-build-workflow', 'rohunj/claude-build-workflow', 'ralph', 0, 0, 60, '2026-03-02T01:56:10.881Z', '2026-03-02T02:08:19.911Z', 'a6a8733abaee5b370957ebd6745a56db88712697fc1262f388d2438b6bbcc021', '{"id":"rohunj/claude-build-workflow/ralph","name":"ralph","description":{"zh":"Ralph是一种自动化工作流构建工具，使用Claude Code描述需求和构建应用程序","ja":"Ralphは、Claude Codeを使用して必要なものを説明し、アプリケーションを構築する自動化ワークフロー構築ツールです","ko":"Ralph는 Claude Code를 사용하여 필요한 것을 설명하고 애플리케이션을 구축하는 자동화 워크플로우 구축 도구입니다","es":"Ralph es una herramienta de automatización de flujos de trabajo que permite a los desarrolladores crear aplicaciones de manera autónoma con Claude Code.","fr":"Ralph est un outil d''automatisation de flux de travail qui permet aux développeurs de créer des applications de manière autonome avec Claude Code.","de":"Ralph ist ein Tool zur Automatisierung von Workflows, das es Entwicklern ermöglicht, Anwendungen autonom mit Claude Code zu erstellen.","pt":"O Ralph é uma ferramenta de automação de fluxo de trabalho que permite aos desenvolvedores criar aplicativos de forma autônoma com Claude Code","ru":"Ralph - это инструмент для автоматизации рабочего процесса, который позволяет разработчикам создавать приложения автономно с помощью Claude Code","ar":"رالف هو أداة تلقائية لتنفيذ تطبيقات تمكن المطورين من إنشاء التطبيقات بشكل مستقل باستخدام Claude Code","en":"Automated workflow for building apps with Claude Code. Describe what you want, answer questions, let it build autonomously."},"seo":{"title":{"zh":"Ralph自动化工作流构建工具","ja":"Ralph自動化ワークフロー構築ツール","ko":"Ralph 자동화 워크플로우 구축 도구","es":"Ralph: Automatización de flujos de trabajo para desarroll...","fr":"Ralph : Automatisation des flux de travail pour les dével...","de":"Ralph: Automatisierung von Workflows für Entwickler","pt":"Ralph: Ferramenta de Automação de Fluxo de Trabalho para ...","ru":"Ralph: Автоматизированный инструмент для разработчиков","ar":"رالف: أداة تلقائية لتنفيذ تطبيقات للطورين","en":"ralph"},"description":{"zh":"Ralph是一种自动化工作流构建工具，使用Claude Code描述需求和构建应用程序","ja":"Ralphは、Claude Codeを使用して必要なものを説明し、アプリケーションを構築する自動化ワークフロー構築ツールです","ko":"Ralph는 Claude Code를 사용하여 필요한 것을 설명하고 애플리케이션을 구축하는 자동화 워크플로우 구축 도구입니다","es":"Ralph es una herramienta de automatización de flujos de trabajo que permite a los desarrolladores crear aplicaciones de manera autónoma con Claude Code.","fr":"Ralph est un outil d''automatisation de flux de travail qui permet aux développeurs de créer des applications de manière autonome avec Claude Code.","de":"Ralph ist ein Tool zur Automatisierung von Workflows, das es Entwicklern ermöglicht, Anwendungen autonom mit Claude Code zu erstellen.","pt":"O Ralph é uma ferramenta de automação de fluxo de trabalho que permite aos desenvolvedores criar aplicativos de forma autônoma com Claude Code","ru":"Ralph - это инструмент для автоматизации рабочего процесса, который позволяет разработчикам создавать приложения автономно с помощью Claude Code","ar":"رالف هو أداة تلقائية لتنفيذ تطبيقات تمكن المطورين من إنشاء التطبيقات بشكل مستقل باستخدام Claude Code","en":"Automated workflow for building apps with Claude Code. Describe what you want, answer questions, let it build autonomously."},"definition":{"en":"Automated workflow for building apps with Claude Code. Describe what you want, answer questions, let it build autonomously."},"features":{"zh":["自动化工作流构建","使用Claude Code描述需求","自主构建应用程序","支持PRD转换","输出prd.json格式"],"ja":["自動化ワークフロー構築","Claude Codeを使用して必要なものを説明","自動でアプリケーションを構築","PRD変換をサポート","prd.json形式を出力"],"ko":["자동화 워크플로우 구축","Claude Code를 사용하여 필요한 것을 설명","자동으로 애플리케이션을 구축","PRD 변환을 지원","prd.json 형식을 출력"],"es":["Conversión de PRDs a formato prd.json","Ejecución autónoma de flujos de trabajo","Integración con Claude Code","Automatización de tareas de desarrollo","Mejora de la eficiencia del desarrollo"],"fr":["Conversion de PRDs au format prd.json","Exécution autonome de flux de travail","Intégration avec Claude Code","Automatisation des tâches de développement","Amélioration de l''efficacité du développement"],"de":["Konvertierung von PRDs in das prd.json-Format","Autonome Ausführung von Workflows","Integration mit Claude Code","Automatisierung von Entwicklungsaufgaben","Verbesserung der EntwicklungsEffizienz"],"pt":["Automação de fluxo de trabalho","Criação de aplicativos autônomos","Integração com Claude Code","Conversão de PRDs para formato prd.json","Execução autônoma de tarefas"],"ru":["Автоматизация рабочего процесса","Создание автономных приложений","Интеграция с Claude Code","Преобразование PRD в формат prd.json","Автономное выполнение задач"],"ar":["التلقين التلقائي لتنفيذ التطبيقات","إنشاء تطبيقات مستقلة","التكامل مع Claude Code","تحويل PRDs إلى تنسيق prd.json","تنفيذ مهام تلقائي"]},"keywords":{"zh":["自动化工作流构建","Claude Code","应用程序构建","PRD转换","prd.json","Ralph","自动化工具"],"ja":["自動化ワークフロー構築","Claude Code","アプリケーション構築","PRD変換","prd.json","Ralph","自動化ツール"],"ko":["자동화 워크플로우 구축","Claude Code","애플리케이션 구축","PRD 변환","prd.json","Ralph","자동화 도구"],"es":["Ralph","automatización de flujos de trabajo","Claude Code","prd.json","desarrollo de aplicaciones","autonomía","eficiencia","desarrollo de software"],"fr":["Ralph","automatisation de flux de travail","Claude Code","prd.json","développement d''applications","autonomie","efficacité","développement de logiciels"],"de":["Ralph","Automatisierung von Workflows","Claude Code","prd.json","Anwendungsentwicklung","Autonomie","Effizienz","Software-Entwicklung"],"pt":["automação de fluxo de trabalho","desenvolvimento de aplicativos","Claude Code","PRD","prd.json","execução autônoma","desenvolvedores"],"ru":["автоматизация рабочего процесса","разработка приложений","Claude Code","PRD","prd.json","автономное выполнение","разработчики"],"ar":["التلقين التلقائي لتنفيذ التطبيقات","تطوير التطبيقات","Claude Code","PRD","prd.json","تنفيذ تلقائي","المطورين"]}},"owner":"rohunj","repo":"claude-build-workflow","repoPath":"rohunj/claude-build-workflow","stars":0,"forks":0,"updatedAt":"2026-03-02T01:56:10.881Z","topics":[],"category":"community","skillMd":{"name":"ralph","description":"Convert PRDs to prd.json format for the Ralph autonomous agent system. Use when you have an existing PRD and need to convert it to Ralphs JSON format. Triggers on: convert this prd, turn this into ralph format, create prd.json from this, ralph json.","bodyPreview":"# Ralph PRD Converter\n\nConverts existing PRDs to the prd.json format that Ralph uses for autonomous execution.\n\n---\n\n## The Job\n\nTake a PRD (markdown file or text) and convert it to `prd.json` in your ralph directory.\n\n---\n\n## Output Format\n\n```json\n{\n  \"project\": \"[Project Name]\",\n  \"branchName\": \"ralph/[feature-name-kebab-case]\",\n  \"description\": \"[Feature description from PRD title/intro]\",\n  \"userStories\": [\n    {\n      \"id\": \"US-001\",\n      \"title\": \"[Story title]\",\n      \"description\": \"As","body":"# Ralph PRD Converter\n\nConverts existing PRDs to the prd.json format that Ralph uses for autonomous execution.\n\n---\n\n## The Job\n\nTake a PRD (markdown file or text) and convert it to `prd.json` in your ralph directory.\n\n---\n\n## Output Format\n\n```json\n{\n  \"project\": \"[Project Name]\",\n  \"branchName\": \"ralph/[feature-name-kebab-case]\",\n  \"description\": \"[Feature description from PRD title/intro]\",\n  \"userStories\": [\n    {\n      \"id\": \"US-001\",\n      \"title\": \"[Story title]\",\n      \"description\": \"As a [user], I want [feature] so that [benefit]\",\n      \"acceptanceCriteria\": [\n        \"Criterion 1\",\n        \"Criterion 2\",\n        \"Typecheck passes\"\n      ],\n      \"priority\": 1,\n      \"passes\": false,\n      \"notes\": \"\"\n    }\n  ]\n}\n```\n\n---\n\n## Story Size: The Number One Rule\n\n**Each story must be completable in ONE Ralph iteration (one context window).**\n\nRalph spawns a fresh Amp instance per iteration with no memory of previous work. If a story is too big, the LLM runs out of context before finishing and produces broken code.\n\n### Right-sized stories:\n- Add a database column and migration\n- Add a UI component to an existing page\n- Update a server action with new logic\n- Add a filter dropdown to a list\n\n### Too big (split these):\n- \"Build the entire dashboard\" - Split into: schema, queries, UI components, filters\n- \"Add authentication\" - Split into: schema, middleware, login UI, session handling\n- \"Refactor the API\" - Split into one story per endpoint or pattern\n\n**Rule of thumb:** If you cannot describe the change in 2-3 sentences, it is too big.\n\n---\n\n## Story Ordering: Dependencies First\n\nStories execute in priority order. Earlier stories must not depend on later ones.\n\n**Correct order:**\n1. Schema/database changes (migrations)\n2. Server actions / backend logic\n3. UI components that use the backend\n4. Dashboard/summary views that aggregate data\n\n**Wrong order:**\n1. UI component (depends on schema that does not exist yet)\n2. Schema change\n\n---\n\n## Acceptance Criteria: Must Be Verifiable\n\nEach criterion must be something Ralph can CHECK, not something vague.\n\n### Good criteria (verifiable):\n- \"Add `status` column to tasks table with default ''pending''\"\n- \"Filter dropdown has options: All, Active, Completed\"\n- \"Clicking delete shows confirmation dialog\"\n- \"Typecheck passes\"\n- \"Tests pass\"\n\n### Bad criteria (vague):\n- \"Works correctly\"\n- \"User can do X easily\"\n- \"Good UX\"\n- \"Handles edge cases\"\n\n### Always include as final criterion:\n```\n\"Typecheck passes\"\n```\n\nFor stories with testable logic, also include:\n```\n\"Tests pass\"\n```\n\n### For stories that change UI, also include:\n```\n\"Verify in browser using dev-browser skill\"\n```\n\nFrontend stories are NOT complete until visually verified. Ralph will use the dev-browser skill to navigate to the page, interact with the UI, and confirm changes work.\n\n---\n\n## Conversion Rules\n\n1. **Each user story becomes one JSON entry**\n2. **IDs**: Sequential (US-001, US-002, etc.)\n3. **Priority**: Based on dependency order, then document order\n4. **All stories**: `passes: false` and empty `notes`\n5. **branchName**: Derive from feature name, kebab-case, prefixed with `ralph/`\n6. **Always add**: \"Typecheck passes\" to every story''s acceptance criteria\n\n---\n\n## Splitting Large PRDs\n\nIf a PRD has big features, split them:\n\n**Original:**\n> \"Add user notification system\"\n\n**Split into:**\n1. US-001: Add notifications table to database\n2. US-002: Create notification service for sending notifications\n3. US-003: Add notification bell icon to header\n4. US-004: Create notification dropdown panel\n5. US-005: Add mark-as-read functionality\n6. US-006: Add notification preferences page\n\nEach is one focused change that can be completed and verified independently.\n\n---\n\n## Example\n\n**Input PRD:**\n```markdown\n# Task Status Feature\n\nAdd ability to mark tasks with different statuses.\n\n## Requirements\n- Toggle between pending/in-progress/done on task list\n- Filter list by status\n- Show status badge on each task\n- Persist status in database\n```\n\n**Output prd.json:**\n```json\n{\n  \"project\": \"TaskApp\",\n  \"branchName\": \"ralph/task-status\",\n  \"description\": \"Task Status Feature - Track task progress with status indicators\",\n  \"userStories\": [\n    {\n      \"id\": \"US-001\",\n      \"title\": \"Add status field to tasks table\",\n      \"description\": \"As a developer, I need to store task status in the database.\",\n      \"acceptanceCriteria\": [\n        \"Add status column: ''pending'' | ''in_progress'' | ''done'' (default ''pending'')\",\n        \"Generate and run migration successfully\",\n        \"Typecheck passes\"\n      ],\n      \"priority\": 1,\n      \"passes\": false,\n      \"notes\": \"\"\n    },\n    {\n      \"id\": \"US-002\",\n      \"title\": \"Display status badge on task cards\",\n      \"description\": \"As a user, I want to see task status at a glance.\",\n      \"acceptanceCriteria\": [\n        \"Each task card shows colored status badge\",\n        \"Badge colors: gray=pending, blue=in_progress, green=done\",\n        \"Typecheck passes\",\n        \"Verify in browser using dev-browser skill\"\n      ],\n      \"priority\": 2,\n      \"passes\": false,\n      \"notes\": \"\"\n    },\n    {\n      \"id\": \"US-003\",\n      \"title\": \"Add status toggle to task list rows\",\n      \"description\": \"As a user, I want to change task status directly from the list.\",\n      \"acceptanceCriteria\": [\n        \"Each row has status dropdown or toggle\",\n        \"Changing status saves immediately\",\n        \"UI updates without page refresh\",\n        \"Typecheck passes\",\n        \"Verify in browser using dev-browser skill\"\n      ],\n      \"priority\": 3,\n      \"passes\": false,\n      \"notes\": \"\"\n    },\n    {\n      \"id\": \"US-004\",\n      \"title\": \"Filter tasks by status\",\n      \"description\": \"As a user, I want to filter the list to see only certain statuses.\",\n      \"acceptanceCriteria\": [\n        \"Filter dropdown: All | Pending | In Progress | Done\",\n        \"Filter persists in URL params\",\n        \"Typecheck passes\",\n        \"Verify in browser using dev-browser skill\"\n      ],\n      \"priority\": 4,\n      \"passes\": false,\n      \"notes\": \"\"\n    }\n  ]\n}\n```\n\n---\n\n## Archiving Previous Runs\n\n**Before writing a new prd.json, check if there is an existing one from a different feature:**\n\n1. Read the current `prd.json` if it exists\n2. Check if `branchName` differs from the new feature''s branch name\n3. If different AND `progress.txt` has content beyond the header:\n   - Create archive folder: `archive/YYYY-MM-DD-feature-name/`\n   - Copy current `prd.json` and `progress.txt` to archive\n   - Reset `progress.txt` with fresh header\n\n**The ralph.sh script handles this automatically** when you run it, but if you are manually updating prd.json between runs, archive first.\n\n---\n\n## Checklist Before Saving\n\nBefore writing prd.json, verify:\n\n- [ ] **Previous run archived** (if prd.json exists with different branchName, archive it first!)\n- [ ] **ALL stories have `passes: false`** (CRITICAL - never copy old pass status!)\n- [ ] Each story is completable in one iteration (small enough)\n- [ ] Stories are ordered by dependency (schema to backend to UI)\n- [ ] Every story has \"Typecheck passes\" as criterion\n- [ ] UI stories have \"Verify in browser\" as criterion\n- [ ] Acceptance criteria are verifiable (not vague)\n- [ ] No story depends on a later story\n\n## CRITICAL: Always Reset passes to false\n\nWhen creating a new prd.json, **ALWAYS** set `passes: false` for every story. Never:\n- Copy pass status from an old prd.json\n- Leave stories marked as `passes: true`\n- Assume previous work carries over\n\nEach new prd.json is a fresh start. The Ralph loop will mark stories as `passes: true` only after successfully implementing them.\n"},"lastSynced":"2026-03-02T02:08:19.911Z","agentAnalysis":{"suitability":{"en":"Ideal for Autonomous Development Agents utilizing Claude Code for app building and workflow automation.","zh":"适用于使用 Claude Code 进行应用开发和工作流自动化的自主开发代理。","ja":"Claude Code を使用してアプリ開発とワークフローの自動化を行う自律開発エージェントに最適です。","ko":"클라우드 코드를 사용하여 애플리케이션 개발 및 워크플로 자동화를 수행하는 자율 개발 에이전트에 적합합니다.","es":"Ideal para Agentes de Desarrollo Autónomos que utilizan Claude Code para la creación de aplicaciones y la automatización de flujos de trabajo.","fr":"Idéal pour les agents de développement autonomes utilisant Claude Code pour la création d''applications et l''automatisation des flux de travail.","de":"Ideal für autonome Entwicklungssagenten, die Claude Code für die Erstellung von Anwendungen und die Automatisierung von Workflows verwenden.","pt":"Ideal para Agentes de Desenvolvimento Autônomo que utilizam Claude Code para construção de aplicativos e automação de fluxos de trabalho.","ru":"Идеально подходит для автономных агентов разработки, использующих Claude Code для создания приложений и автоматизации рабочих процессов.","ar":"مثالي لعمليات التطوير المستقلة التي تستخدم Claude Code لبناء التطبيقات وآليّة اتخاذ الإجراءات"},"recommendation":{"en":"Empowers agents to autonomously execute workflows by converting existing PRDs to the prd.json format, leveraging markdown files or text, and utilizing the ralph directory for seamless project integration with JSON output formats.","zh":"使代理能够通过将现有的 PRD 转换为 prd.json 格式、利用 markdown 文件或文本以及利用 ralph 目录来实现无缝的项目集成和 JSON 输出格式来自治执行工作流。","ja":"エージェントが既存の PRD を prd.json 形式に変換し、マークダウンファイルまたはテキストを利用し、ralph ディレクトリを使用してプロジェクトの統合と JSON 出力形式を無縫に実現することで、ワークフローを自律的に実行できるようにします。","ko":"기존의 PRD를 prd.json 형식으로 변환하고, 마크다운 파일이나 텍스트를 활용하며, ralph 디렉토리를 사용하여 프로젝트 통합과 JSON 출력 형식을无缝하게 구현함으로써 에이전트가 워크플ロー를 자율적으로 실행할 수 있도록 합니다.","es":"Permite a los agentes ejecutar flujos de trabajo de forma autónoma convirtiendo los PRD existentes al formato prd.json, aprovechando archivos markdown o texto y utilizando el directorio ralph para una integración de proyectos sin problemas con formatos de salida JSON.","fr":"Permet aux agents d''exécuter des flux de travail de manière autonome en convertissant les PRD existants au format prd.json, en exploitant les fichiers markdown ou le texte et en utilisant le répertoire ralph pour une intégration de projets transparente avec des formats de sortie JSON.","de":"Ermöglicht es Agenten, Workflows autonom auszuführen, indem sie vorhandene PRD im prd.json-Format konvertieren, Markdown-Dateien oder Text nutzen und das ralph-Verzeichnis für eine nahtlose Projektintegration mit JSON-Ausgabeformaten verwenden.","pt":"Habilita os agentes a executar fluxos de trabalho de forma autônoma, convertendo PRDs existentes para o formato prd.json, utilizando arquivos markdown ou texto e utilizando o diretório ralph para integração de projeto sem interrupções com formatos de saída JSON.","ru":"Позволяет агентам автономно выполнять рабочие процессы, преобразуя существующие PRD в формат prd.json, используя файлы markdown или текст и используя каталог ralph для бесшовной интеграции проекта с форматами вывода JSON.","ar":"تمكّن الوكلاء من تنفيذ سير العمل بشكل مستقل عن طريق تحويل مواصفات المنتج الموجودة إلى صيغة prd.json، واستخدام ملفات markdown أو نص، واستخدام دليل ralph من أجل دمج مشروع متكامل مع تنسيقات إخراج JSON."},"useCases":{"en":["Converting PRDs to prd.json for autonomous execution","Automating app development workflows with Claude Code","Generating project configurations in ralph directory"],"zh":["将 PRD 转换为 prd.json 以实现自主执行","使用 Claude Code 自动化应用开发工作流","在 ralph 目录中生成项目配置"],"ja":["PRD を prd.json に変換して自律実行を可能にする","Claude Code を使用してアプリ開発ワークフローを自動化する","ralph ディレクトリ内でプロジェクト構成を生成する"],"ko":["PRD를 prd.json으로 변환하여 자율 실행을 가능하게 함","클라우드 코드를 사용하여 애플리케이션 개발 워크플ロー 자동화","ralph 디렉토리에서 프로젝트 구성 생성"],"es":["Conversión de PRD a prd.json para ejecución autónoma","Automatización de flujos de trabajo de desarrollo de aplicaciones con Claude Code","Generación de configuraciones de proyecto en el directorio ralph"],"fr":["Conversion de PRD en prd.json pour exécution autonome","Automatisation des flux de travail de développement d''applications avec Claude Code","Génération de configurations de projet dans le répertoire ralph"],"de":["Konvertierung von PRD in prd.json für autonome Ausführung","Automatisierung von App-Entwicklungsworkflows mit Claude Code","Generierung von Projekt-Konfigurationen im ralph-Verzeichnis"],"pt":["Conversão de PRDs para prd.json para execução autônoma","Automação de fluxos de trabalho de desenvolvimento de aplicativos com Claude Code","Geração de configurações de projeto no diretório ralph"],"ru":["Преобразование PRD в формат prd.json для автономного выполнения","Автоматизация рабочих процессов разработки приложений с помощью Claude Code","Генерация конфигураций проекта в каталоге ralph"],"ar":["تحويل مواصفات المنتج إلى صيغة prd.json من أجل التنفيذ المستقل","آليّة تطوير التطبيقات مع Claude Code","توليد تكوين المشروع في دليل ralph"]},"limitations":{"en":["Requires existing PRD in markdown or text format","Specific to ralph directory and prd.json format"],"zh":["需要现有的 PRD 以 markdown 或文本格式存在","仅限于 ralph 目录和 prd.json 格式"],"ja":["既存の PRD がマークダウンまたはテキスト形式で存在する必要がある","ralph ディレクトリと prd.json 形式に限定される"],"ko":["기존의 PRD가 마크다운 또는 텍스트 형식으로 존재해야 함","ralph 디렉토리와 prd.json 형식으로 제한됨"],"es":["Requiere un PRD existente en formato markdown o texto","Específico del directorio ralph y del formato prd.json"],"fr":["Nécessite un PRD existant au format markdown ou texte","Spécifique au répertoire ralph et au format prd.json"],"de":["Benötigt ein vorhandenes PRD im Markdown- oder Textformat","Spezifisch für das ralph-Verzeichnis und das prd.json-Format"],"pt":["Exige PRD existente em formato markdown ou texto","Específico para diretório ralph e formato prd.json"],"ru":["Требует существующей PRD в формате markdown или текста","Специфичен для каталога ralph и формата prd.json"],"ar":["يتطلب مواصفات منتج موجودة في صيغة markdown أو نص","محدد لدليل ralph و صيغة prd.json"]},"version":3},"contentHash":"a6a8733abaee5b370957ebd6745a56db88712697fc1262f388d2438b6bbcc021","qualityScore":60}');
